ALTER TABLE "doctor_scheduling_settings" ADD CONSTRAINT "doctor_scheduling_settings_doctor_id_doctors_id_fk" FOREIGN KEY ("doctor_id") REFERENCES "public"."doctors"("id") ON DELETE no action ON UPDATE no action;
