-- Binds `rule_type` to its required columns. `weekly` needs a day-of-week
-- and both times, no specific date. `custom_hours` needs a specific date and
-- both times, no day-of-week. `blocked` needs a specific date, no
-- day-of-week, and either no times at all (a full-day block) or both times
-- (a partial-day block) — never just one.
ALTER TABLE "doctor_availability" ADD CONSTRAINT "doctor_availability_rule_shape_check" CHECK (
	(
		"doctor_availability"."rule_type" = 'weekly'
		AND "doctor_availability"."day_of_week" IS NOT NULL
		AND "doctor_availability"."specific_date" IS NULL
		AND "doctor_availability"."start_time" IS NOT NULL
		AND "doctor_availability"."end_time" IS NOT NULL
	)
	OR (
		"doctor_availability"."rule_type" = 'custom_hours'
		AND "doctor_availability"."day_of_week" IS NULL
		AND "doctor_availability"."specific_date" IS NOT NULL
		AND "doctor_availability"."start_time" IS NOT NULL
		AND "doctor_availability"."end_time" IS NOT NULL
	)
	OR (
		"doctor_availability"."rule_type" = 'blocked'
		AND "doctor_availability"."day_of_week" IS NULL
		AND "doctor_availability"."specific_date" IS NOT NULL
		AND (
			("doctor_availability"."start_time" IS NULL AND "doctor_availability"."end_time" IS NULL)
			OR ("doctor_availability"."start_time" IS NOT NULL AND "doctor_availability"."end_time" IS NOT NULL)
		)
	)
);
--> statement-breakpoint
-- Whenever both times are present (any rule_type), the range must be
-- non-empty and forward — end strictly after start.
ALTER TABLE "doctor_availability" ADD CONSTRAINT "doctor_availability_time_order_check" CHECK (
	"doctor_availability"."start_time" IS NULL
	OR "doctor_availability"."end_time" IS NULL
	OR "doctor_availability"."end_time" > "doctor_availability"."start_time"
);